class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False  # viz:uneven
        counts = Counter(s)  # viz:count
        for c in t:
            if counts[c] == 0:  # viz:check
                return False  # viz:ran_out
            counts[c] -= 1  # viz:use
        return True  # viz:done
